INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9524, 'koKR', 'Uwięziona w cytadeli', 'Przymierze, tutaj?! Słuchaj uważnie, $N.$B$BKargath pojmał kilku naszych żołnierzy. Jest wśród nich kapitan Alina, ważna oficer. Musisz spróbować ją uratować, zanim zostanie stracona.$B$BNie martw się o mnie, znajdę sposób, żeby się wydostać, jak tylko złapię oddech.', 'Uratuj kapitan Alinę w Cytadeli Piekielnego Ognia, zanim zostanie stracona.$B$BTo zadanie trzeba ukończyć na heroicznym poziomie trudności lochu.', '', 'Wróć do kapitan Aliny na Przylądku Gavina w Górach Alterak.', 'Kapitan Alina uratowana', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9524, 'koKR', 'Dziękuję ci, $N. Przyznaję, że nie spodziewałam się, że ktoś ruszy nam na ratunek.$B$BZbiorę pozostałych więźniów i zaprowadzę ich z powrotem do Warowni Honoru.', 0);
