INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13721, 'koKR', 'Przymierze śmie zapuszczać się tak głęboko w moją twierdzę? Przyprowadzić więźniów z Warowni Honoru i wezwać kata! Zapłacą życiem za to wtargnięcie!', '', 0),
(13722, 'koKR', 'Fałszywa Horda Thralla śmie zapuszczać się tak głęboko w moją twierdzę? Przyprowadzić więźniów z Thrallmaru i wezwać kata! Zapłacą życiem za to wtargnięcie!', '', 0),
(14029, 'koKR', '%s ryczy!', '', 0),
(14043, 'koKR', 'Ja nie lubić tego tu...', '', 0),
(14044, 'koKR', 'Hej, ty zakuty łbie!', '', 0),
(14045, 'koKR', 'My zabić jego przyjaciel!', '', 0),
(14046, 'koKR', 'Miażdżyć!', '', 0),
(14047, 'koKR', 'Może pozwolisz, że to ja będę mówił?', '', 0),
(14048, 'koKR', 'Jak ty miły, ja pozwolić ci żyć.', '', 0),
(14130, 'koKR', 'Błagaj o swoje marne życie!', '', 0),
(14132, 'koKR', 'Uciekaj, tchórzu, uciekaj!', '', 0),
(14136, 'koKR', 'To boleć!', '', 0),
(14137, 'koKR', 'Aaa! Nie boleć więcej!', '', 0),
(14138, 'koKR', 'To nie dobre łaskotki!', '', 0),
(14139, 'koKR', 'Skóra płonąć!', '', 0),
(14140, 'koKR', 'To boleć!', '', 0),
(14141, 'koKR', 'Aaaach!', '', 0),
(14142, 'koKR', 'Nie straszyć więcej!', '', 0),
(14144, 'koKR', 'Dość!', '', 0),
(14148, 'koKR', 'Twój ból mnie bawi!', '', 0),
(14149, 'koKR', 'Ból!', '', 0),
(14150, 'koKR', 'Boli!', '', 0),
(14151, 'koKR', 'Graaaggh!!', '', 0),
(14152, 'koKR', 'Dość!!', '', 0),
(14309, 'koKR', 'Najeźdźcy przełamali obronę!', '', 0),
(14310, 'koKR', 'Łucznicy, w szereg! Na mój znak!', '', 0),
(14311, 'koKR', 'Gotowi!', '', 0),
(15569, 'koKR', 'Możecie wziąć tego, już go nie potrzebuję!', '', 0),
(15572, 'koKR', 'Chcecie go? Dobrze, bierzcie!', '', 0),
(15573, 'koKR', 'Nie traćcie czasu na tego, jest słaby!', '', 0),
(15575, 'koKR', 'Tak, bijcie go bez litości! Ma czaszkę grubą jak ogr!\n', '', 0),
(15579, 'koKR', 'Jeden nędznik mniej. No dalej, bierzcie następnego!', '', 0),
(15582, 'koKR', 'I tak zamierzałem go zabić!', '', 0),
(15584, 'koKR', 'Ach, co za marnotrawstwo... następny!', '', 0),
(15589, 'koKR', 'Dziękuję, że oszczędziliście mi kłopotu. Teraz moja kolej na zabawę!\n', '', 0),
(15594, 'koKR', 'Chcecie walczyć z nami wszystkimi naraz? To może być zabawne!\n', '', 0),
(15595, 'koKR', 'No dalej, pokażcie mi prawdziwą walkę!', '', 0),
(16862, 'koKR', 'Cóż... za szkoda.', '', 0),
(16863, 'koKR', 'Więcej zabawy miałem przy torturowaniu parobków!', '', 0),
(16864, 'koKR', 'Już się nudzę!', '', 0),
(16865, 'koKR', 'Przegraliście.', '', 0),
(16866, 'koKR', 'Och, po prostu giń!', '', 0),
(16895, 'koKR', 'My zabić kogoś innego!', '', 0),
(16896, 'koKR', 'Jeszcze nie skończyłem, idioto!', '', 0),
(16898, 'koKR', 'Ty zostać tu. Ja iść zabić kogoś innego!', '', 0),
(16899, 'koKR', 'To nie jest śmieszne!', '', 0),
(16900, 'koKR', 'Ha ha ha.', '', 0),
(16901, 'koKR', 'Co ty wyprawiasz?', '', 0),
(16902, 'koKR', 'Ja się znudzić.', '', 0),
(16903, 'koKR', 'Znudzić? Przecież prawie nie żył!', '', 0),
(16916, 'koKR', 'Nie, NIE pozwolimy ci żyć.', '', 0),
(16917, 'koKR', 'Hej!', '', 0),
(16918, 'koKR', 'Ja głodny.', '', 0),
(16919, 'koKR', 'Ty zawsze głodny. Dlatego my tacy grubi!', '', 0),
(16921, 'koKR', 'Jestem zmęczony. Ty zabij następnego!', '', 0),
(16922, 'koKR', 'Ten umierać łatwo!', '', 0),
(16923, 'koKR', 'Bo to ja odwalam całą ciężką robotę!', '', 0),
(16924, 'koKR', 'To wszystko... twoja wina!', '', 0),
(16925, 'koKR', 'Nie... znoszę... cię.', '', 0),
(17614, 'koKR', 'To nasza Horda jest PRAWDZIWA! Jedyna Horda!', '', 0),
(17616, 'koKR', 'Obedrę twoje kości z mięsa!', '', 0),
(17617, 'koKR', 'Nie bez powodu zwą mnie Brzytworękim. Zaraz się przekonacie.', '', 0),
(17619, 'koKR', 'Za prawdziwą Hordę!', '', 0),
(17620, 'koKR', 'Jestem JEDYNYM wodzem wojennym!', '', 0),
(17621, 'koKR', 'Prawdziwa Horda... zwycięży.', '', 0),
(17910, 'koKR', 'Celuj!', '', 0),
(18367, 'koKR', 'Tchórze! Nigdy nie zwabicie mnie w cień!', '', 0);
